-- Generated by Supabase CLI 3.0.0: migration new mealdeck_marketplace_connectors.
-- Independent MealDeck marketplace ledger. This does not create Stripe/cash
-- payments, alter direct-order authority, activate an adapter, or send a command.
begin;
set local lock_timeout='5s';

do $guard$ begin
  if to_regnamespace('dishbee_private') is not null
    or to_regclass('mealdeck_private.installation') is null then
    raise exception 'mealdeck_marketplace_independent_profile_required'; end if;
  if not exists(select 1 from mealdeck_private.installation where singleton
      and profile='mealdeck-independent-v1')
    or to_regprocedure('mealdeck_ops_private.kds_assert_scope(uuid,uuid,text)') is null
    or to_regprocedure('mealdeck_private.paid_order_number(uuid)') is null
    or to_regprocedure('public.mealdeck_ops_kds_workflow_board(uuid,uuid)') is null then
    raise exception 'mealdeck_marketplace_previous_extensions_required'; end if;
  if not exists(select 1 from pg_proc where oid=
      'public.mealdeck_ops_kds_workflow_board(uuid,uuid)'::regprocedure
      and md5(prosrc)='ea32c882fcb966a568d53b5396e9aae1'
      and prosecdef and proconfig @> array['search_path=""']) then
    raise exception 'mealdeck_marketplace_unreviewed_workflow_board'; end if;
end $guard$;

create table mealdeck_private.marketplace_connectors(
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null,location_id uuid not null,
  platform text not null check(platform in ('uber_eats','just_eat')),
  external_store_id text not null check(length(external_store_id) between 1 and 200),
  label text not null check(length(label) between 1 and 120),
  station_id uuid not null,brand_id uuid,
  token_hash text not null check(token_hash ~ '^[a-f0-9]{64}$'),
  profile_id text not null check(length(profile_id) between 1 and 120),
  profile_version text not null check(length(profile_version) between 1 and 80),
  capabilities jsonb not null,
  enabled boolean not null default false,
  commissioned_at timestamptz,commissioning_reference text,permission_reference text,
  last_seen_at timestamptz,health_status text not null default 'unconfigured'
    check(health_status in ('unconfigured','healthy','degraded')),
  health_error_code text check(health_error_code in (
    'ui_unavailable','identity_mismatch','profile_mismatch','session_required',
    'device_unavailable','observation_incomplete','command_uncertain','bridge_error')),
  created_at timestamptz not null default now(),
  unique(platform,external_store_id),unique(tenant_id,location_id,id),
  foreign key(tenant_id,location_id) references public.tenant_locations(tenant_id,id),
  foreign key(tenant_id,location_id,station_id)
    references public.kitchen_stations(tenant_id,location_id,id),
  foreign key(tenant_id,brand_id) references public.tenant_brands(tenant_id,id),
  check(not enabled or (commissioned_at is not null and
    length(commissioning_reference) between 1 and 500 and length(permission_reference) between 1 and 500)),
  check(not (health_status='healthy' and health_error_code is not null)),
  check(jsonb_typeof(capabilities)='object' and
    capabilities ?& array['accept','preparing','ready','handover'] and
    capabilities-array['accept','preparing','ready','handover']='{}'::jsonb and
    jsonb_typeof(capabilities->'accept')='boolean' and
    jsonb_typeof(capabilities->'preparing')='boolean' and
    jsonb_typeof(capabilities->'ready')='boolean' and
    jsonb_typeof(capabilities->'handover')='boolean')
);

-- These are marketplace-owned orders, not direct MealDeck checkout orders.
-- The immutable observed snapshot records the platform's commercial terms.
-- It is never repriced with MealDeck offers or used to create a payment.
create table mealdeck_private.marketplace_orders(
  id uuid primary key default gen_random_uuid(),connector_id uuid not null,
  tenant_id uuid not null,location_id uuid not null,
  external_order_id text not null check(length(external_order_id) between 1 and 200),
  display_reference text not null check(length(display_reference) between 1 and 80),
  snapshot jsonb not null check(jsonb_typeof(snapshot)='object'),
  fulfilment text not null check(fulfilment in ('collection','platform_delivery','merchant_delivery')),
  currency text not null check(currency='GBP'),
  total_pence integer not null check(total_pence between 0 and 10000000),
  placed_at timestamptz not null,received_at timestamptz not null default now(),
  notes text check(length(notes)<=1000),
  platform_state text not null check(platform_state in ('new','accepted','preparing','ready','handed_over','cancelled')),
  observed_at timestamptz not null,
  hold_reason text check(hold_reason in ('snapshot_changed','state_regressed')),
  imported_after_handover boolean not null default false,
  accepted_at timestamptz,preparing_at timestamptz,ready_at timestamptz,
  packing_at timestamptz,sealed_at timestamptz,handed_over_at timestamptz,
  cancellation_acknowledged_at timestamptz,cancellation_acknowledged_by uuid references auth.users(id),
  revision bigint not null default 1 check(revision>0),
  unique(connector_id,external_order_id),unique(connector_id,id),
  foreign key(tenant_id,location_id,connector_id)
    references mealdeck_private.marketplace_connectors(tenant_id,location_id,id),
  check(preparing_at is null or accepted_at is not null),
  check(ready_at is null or preparing_at is not null),
  check(packing_at is null or ready_at is not null),
  check(sealed_at is null or packing_at is not null),
  check(handed_over_at is null or sealed_at is not null)
);
create index marketplace_orders_board on mealdeck_private.marketplace_orders(tenant_id,location_id,received_at,id)
  where handed_over_at is null and not imported_after_handover and cancellation_acknowledged_at is null;
create index marketplace_orders_completed on mealdeck_private.marketplace_orders(tenant_id,location_id,handed_over_at desc)
  where handed_over_at is not null;

create table mealdeck_private.marketplace_order_items(
  id uuid primary key default gen_random_uuid(),order_id uuid not null,
  connector_id uuid not null,external_line_id text not null,
  position integer not null check(position between 1 and 200),
  name text not null check(length(name) between 1 and 300),
  quantity integer not null check(quantity between 1 and 999),
  unit_price_pence integer check(unit_price_pence between 0 and 10000000),
  modifiers jsonb not null check(jsonb_typeof(modifiers)='array' and jsonb_array_length(modifiers)<=100),
  notes text check(length(notes)<=1000),ready_at timestamptz,
  unique(order_id,external_line_id),unique(order_id,position),
  foreign key(connector_id,order_id) references mealdeck_private.marketplace_orders(connector_id,id)
);

-- Only changed observations are kept, avoiding a full snapshot per poll.
-- Conflicting snapshots remain private and hold the original ticket for review.
create table mealdeck_private.marketplace_observations(
  id uuid primary key default gen_random_uuid(),sequence bigint generated always as identity,connector_id uuid not null,
  order_id uuid not null,observed_at timestamptz not null,
  platform_state text not null,snapshot jsonb not null,
  profile_id text not null,profile_version text not null,
  received_at timestamptz not null default now(),
  foreign key(connector_id,order_id) references mealdeck_private.marketplace_orders(connector_id,id)
);
create index marketplace_observations_order on mealdeck_private.marketplace_observations(order_id,sequence desc);

create table mealdeck_private.marketplace_commands(
  id uuid primary key default gen_random_uuid(),sequence bigint generated always as identity,
  connector_id uuid not null,order_id uuid not null,
  action text not null check(action in ('accept','preparing','ready','handover')),
  status text not null check(status in ('queued','sending','confirmed','needs_checking','unsupported')),
  actor_id uuid not null references auth.users(id),created_at timestamptz not null default now(),
  lease_token uuid,lease_expires_at timestamptz,
  -- At most one execute claim. Any expired claim is reconciliation-only.
  execute_claimed_at timestamptz,reconcile_claimed_at timestamptz,
  confirmed_at timestamptz,result_outcome text,observed_state text,result_readback_at timestamptz,
  result_profile_id text,result_profile_version text,
  unique(order_id,action),
  foreign key(connector_id,order_id) references mealdeck_private.marketplace_orders(connector_id,id),
  check((lease_token is null)=(lease_expires_at is null))
);
create index marketplace_commands_work on mealdeck_private.marketplace_commands(connector_id,sequence)
  where status in ('queued','sending','needs_checking');

do $security$ declare t text; begin
  foreach t in array array['marketplace_connectors','marketplace_orders','marketplace_order_items',
    'marketplace_observations','marketplace_commands'] loop
    execute format('alter table mealdeck_private.%I enable row level security',t);
    execute format('revoke all on mealdeck_private.%I from public,anon,authenticated,service_role',t);
  end loop;
end $security$;
revoke all on sequence mealdeck_private.marketplace_commands_sequence_seq from public,anon,authenticated,service_role;
revoke all on sequence mealdeck_private.marketplace_observations_sequence_seq from public,anon,authenticated,service_role;

create function mealdeck_private.marketplace_timestamp(p_value timestamptz)
returns text language sql immutable security invoker set search_path='' as $$
  select to_char(p_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
$$;
create function mealdeck_private.marketplace_plain(p_value text,p_limit integer,p_notes boolean default false)
returns boolean language sql immutable security invoker set search_path='' as $$
  select coalesce(length(p_value)<=p_limit and (p_notes or length(btrim(p_value))>0)
    and (case when p_notes then replace(replace(p_value,chr(10),''),chr(9),'') else p_value end) !~ '[[:cntrl:]]'
    and p_value !~ U&'[\00ad\061c\200b-\200f\2028-\202e\2060-\206f\feff]',false)
$$;
create function mealdeck_private.marketplace_state_rank(p_state text)
returns integer language sql immutable security invoker set search_path='' as $$
  select case p_state when 'new' then 0 when 'accepted' then 1 when 'preparing' then 2
    when 'ready' then 3 when 'handed_over' then 4 when 'cancelled' then 5 else -1 end
$$;

create function mealdeck_private.marketplace_preserve_connector_identity()
returns trigger language plpgsql security invoker set search_path='' as $$
begin
  if row(new.id,new.tenant_id,new.location_id,new.platform,new.external_store_id)
    is distinct from row(old.id,old.tenant_id,old.location_id,old.platform,old.external_store_id)
    or (row(new.station_id,new.brand_id) is distinct from row(old.station_id,old.brand_id)
      and exists(select 1 from mealdeck_private.marketplace_orders where connector_id=old.id)) then
    raise exception 'mealdeck_marketplace_immutable_connector'; end if;
  if row(new.profile_id,new.profile_version,new.capabilities) is distinct from row(old.profile_id,old.profile_version,old.capabilities)
    and (old.enabled or new.enabled or new.commissioned_at is not null) then
    raise exception 'mealdeck_marketplace_profile_recommission_required'; end if;
  return new;
end $$;
create trigger marketplace_preserve_connector_identity before update on mealdeck_private.marketplace_connectors
  for each row execute function mealdeck_private.marketplace_preserve_connector_identity();
create function mealdeck_private.marketplace_action_observed(p_action text,p_state text)
returns boolean language sql immutable security invoker set search_path='' as $$
  select p_state<>'cancelled' and case p_action
    when 'accept' then p_state in ('accepted','preparing','ready','handed_over')
    when 'preparing' then p_state in ('preparing','ready','handed_over')
    when 'ready' then p_state in ('ready','handed_over')
    when 'handover' then p_state='handed_over' else false end
$$;

-- Provisioning is deliberately operator-only and always starts disabled. It
-- needs actual store/device evidence, not an arbitrary browser tenant or SKU.
create function mealdeck_private.marketplace_provision_connector(
  p_tenant uuid,p_location uuid,p_platform text,p_external_store_id text,p_label text,
  p_station uuid,p_brand uuid,p_token_hash text,p_profile_id text,p_profile_version text,p_capabilities jsonb
) returns uuid language plpgsql security invoker set search_path='' as $$
declare result uuid;
begin
  if p_platform not in ('uber_eats','just_eat')
    or not mealdeck_private.marketplace_plain(p_external_store_id,200)
    or not mealdeck_private.marketplace_plain(p_label,120)
    or not mealdeck_private.marketplace_plain(p_profile_id,120)
    or not mealdeck_private.marketplace_plain(p_profile_version,80)
    or p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$'
    or not exists(select 1 from public.tenant_locations where id=p_location and tenant_id=p_tenant and active)
    or not exists(select 1 from public.kitchen_stations where id=p_station and tenant_id=p_tenant and location_id=p_location and active)
    or (p_brand is not null and not exists(select 1 from public.tenant_brands where id=p_brand and tenant_id=p_tenant)) then
    raise exception 'mealdeck_marketplace_invalid_connector'; end if;
  insert into mealdeck_private.marketplace_connectors(tenant_id,location_id,platform,external_store_id,label,
    station_id,brand_id,token_hash,profile_id,profile_version,capabilities)
    values(p_tenant,p_location,p_platform,p_external_store_id,p_label,p_station,p_brand,p_token_hash,
      p_profile_id,p_profile_version,p_capabilities) returning id into result;
  return result;
end $$;

create function mealdeck_private.marketplace_commission_connector(
  p_connector uuid,p_permission_reference text,p_device_acceptance_reference text
) returns void language plpgsql security invoker set search_path='' as $$
begin
  if not mealdeck_private.marketplace_plain(p_permission_reference,500)
    or not mealdeck_private.marketplace_plain(p_device_acceptance_reference,500) then
    raise exception 'mealdeck_marketplace_commissioning_required'; end if;
  update mealdeck_private.marketplace_connectors set enabled=true,commissioned_at=now(),
    permission_reference=p_permission_reference,commissioning_reference=p_device_acceptance_reference,
    last_seen_at=null,health_status='unconfigured',health_error_code=null where id=p_connector;
  if not found then raise exception 'mealdeck_marketplace_invalid_connector'; end if;
end $$;

create function mealdeck_private.marketplace_version(p_order uuid)
returns text language sql stable security definer set search_path='' as $$
  select md5(jsonb_build_array(o.id,o.revision,o.platform_state,o.hold_reason,
    o.accepted_at,o.preparing_at,o.ready_at,o.packing_at,o.sealed_at,o.handed_over_at,o.cancellation_acknowledged_at,
    c.enabled,c.commissioned_at,c.profile_id,c.profile_version,c.capabilities,
    s.active,(select jsonb_agg(jsonb_build_array(i.id,i.ready_at) order by i.position)
      from mealdeck_private.marketplace_order_items i where i.order_id=o.id))::text)
  from mealdeck_private.marketplace_orders o join mealdeck_private.marketplace_connectors c on c.id=o.connector_id
    join public.kitchen_stations s on s.id=c.station_id and s.tenant_id=c.tenant_id and s.location_id=c.location_id
  where o.id=p_order
$$;

create function mealdeck_private.marketplace_metadata(p_order uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare o mealdeck_private.marketplace_orders%rowtype;c mealdeck_private.marketplace_connectors%rowtype;
  cmd mealdeck_private.marketplace_commands%rowtype;sync text;pending text;
begin
  select * into o from mealdeck_private.marketplace_orders where id=p_order;
  select * into c from mealdeck_private.marketplace_connectors where id=o.connector_id;
  select * into cmd from mealdeck_private.marketplace_commands where order_id=p_order
    order by case when status in ('queued','sending','needs_checking') then 0 else 1 end,
      case when status in ('queued','sending','needs_checking') then sequence end,sequence desc limit 1;
  pending:=case when cmd.status<>'confirmed' then cmd.action else null end;
  sync:=case when not c.enabled or c.commissioned_at is null then 'unconfigured'
    when o.hold_reason is not null or o.platform_state='cancelled' then 'needs_checking'
    when cmd.status='needs_checking' then 'needs_checking'
    when cmd.status='sending' and cmd.lease_expires_at<=now() then 'needs_checking'
    when cmd.status='sending' then 'sending'
    when cmd.status='queued' then 'queued'
    when cmd.status='unsupported' then 'unsupported'
    when c.health_status<>'healthy' or c.last_seen_at is null or c.last_seen_at<now()-interval '2 minutes' then 'needs_checking'
    when exists(select 1 from mealdeck_private.marketplace_commands where order_id=p_order and status='confirmed') then 'confirmed'
    else 'idle' end;
  return jsonb_build_object('platform',c.platform,'display_reference',o.display_reference,
    'platform_state',o.platform_state,'confirmed_at',mealdeck_private.marketplace_timestamp(o.observed_at),
    'sync_state',sync,'pending_action',pending,'capabilities',c.capabilities);
end $$;

-- Defend the authenticated service boundary independently of HTTP validation.
-- Null prices remain unknown; customer-total differences are never recomputed.
create function mealdeck_private.marketplace_normalise_observation(p_input jsonb)
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare item jsonb;modifier jsonb;items jsonb:='[]';modifiers jsonb;
  placed timestamptz;observed timestamptz;line_ids text[]:='{}';
begin
  if jsonb_typeof(p_input) is distinct from 'object'
    or p_input-array['platform','externalStoreId','externalOrderId','displayReference','state','fulfilment',
      'paymentResponsibility','currency','totalPence','placedAt','observedAt','items','notes','evidence']<>'{}'::jsonb
    or coalesce(p_input->>'platform','') not in ('uber_eats','just_eat')
    or coalesce(p_input->>'state','') not in ('new','accepted','preparing','ready','handed_over','cancelled')
    or coalesce(p_input->>'fulfilment','') not in ('collection','platform_delivery','merchant_delivery')
    or p_input->>'paymentResponsibility' is distinct from 'platform' or p_input->>'currency' is distinct from 'GBP'
    or not mealdeck_private.marketplace_plain(p_input->>'externalStoreId',200)
    or not mealdeck_private.marketplace_plain(p_input->>'externalOrderId',200)
    or not mealdeck_private.marketplace_plain(p_input->>'displayReference',80)
    or p_input->>'externalStoreId'<>btrim(p_input->>'externalStoreId')
    or p_input->>'externalOrderId'<>btrim(p_input->>'externalOrderId')
    or p_input->>'displayReference'<>btrim(p_input->>'displayReference')
    or jsonb_typeof(p_input->'totalPence') is distinct from 'number'
    or coalesce(p_input->>'totalPence','') !~ '^[0-9]+$'
    or (p_input->>'totalPence')::numeric>10000000
    or (p_input->>'notes' is not null and (jsonb_typeof(p_input->'notes')<>'string'
      or not mealdeck_private.marketplace_plain(p_input->>'notes',1000,true)))
    or jsonb_typeof(p_input->'items') is distinct from 'array'
    or jsonb_array_length(p_input->'items') not between 1 and 200 then
    raise exception 'mealdeck_marketplace_invalid_observation'; end if;
  placed:=(p_input->>'placedAt')::timestamptz;observed:=(p_input->>'observedAt')::timestamptz;
  if placed is null or observed is null or not isfinite(placed) or not isfinite(observed)
    or placed>now()+interval '30 seconds' or placed<now()-interval '7 days'
    or observed<now()-interval '5 minutes' or observed>now()+interval '30 seconds'
    or placed>observed+interval '30 seconds' then
    raise exception 'mealdeck_marketplace_stale_observation'; end if;
  for item in select value from jsonb_array_elements(p_input->'items') loop
    if jsonb_typeof(item)<>'object' or item-array['externalLineId','name','quantity','unitPricePence','modifiers','notes']<>'{}'::jsonb
      or not mealdeck_private.marketplace_plain(item->>'externalLineId',200)
      or not mealdeck_private.marketplace_plain(item->>'name',300)
      or item->>'externalLineId'=any(line_ids)
      or jsonb_typeof(item->'quantity') is distinct from 'number'
      or coalesce(item->>'quantity','') !~ '^[0-9]+$' or (item->>'quantity')::numeric not between 1 and 999
      or not item ? 'unitPricePence'
      or (item->'unitPricePence'<>'null'::jsonb and (jsonb_typeof(item->'unitPricePence')<>'number'
        or coalesce(item->>'unitPricePence','') !~ '^[0-9]+$' or (item->>'unitPricePence')::numeric>10000000))
      or (item->>'notes' is not null and (jsonb_typeof(item->'notes')<>'string'
        or not mealdeck_private.marketplace_plain(item->>'notes',1000,true)))
      or jsonb_typeof(item->'modifiers') is distinct from 'array' or jsonb_array_length(item->'modifiers')>100 then
      raise exception 'mealdeck_marketplace_invalid_observation'; end if;
    line_ids:=array_append(line_ids,item->>'externalLineId');modifiers:='[]'::jsonb;
    for modifier in select value from jsonb_array_elements(item->'modifiers') loop
      if jsonb_typeof(modifier)<>'object' or modifier-array['name','quantity']<>'{}'::jsonb
        or not mealdeck_private.marketplace_plain(modifier->>'name',300)
        or jsonb_typeof(modifier->'quantity') is distinct from 'number'
        or coalesce(modifier->>'quantity','') !~ '^[0-9]+$'
        or (modifier->>'quantity')::numeric not between 1 and 999 then
        raise exception 'mealdeck_marketplace_invalid_observation'; end if;
      modifiers:=modifiers||jsonb_build_array(jsonb_build_object('name',modifier->>'name','quantity',(modifier->>'quantity')::integer));
    end loop;
    items:=items||jsonb_build_array(jsonb_build_object('externalLineId',item->>'externalLineId','name',item->>'name',
      'quantity',(item->>'quantity')::integer,'unitPricePence',(item->>'unitPricePence')::integer,
      'modifiers',modifiers,'notes',item->>'notes'));
  end loop;
  return jsonb_build_object('platform',p_input->>'platform','externalStoreId',p_input->>'externalStoreId',
    'externalOrderId',p_input->>'externalOrderId','displayReference',p_input->>'displayReference',
    'fulfilment',p_input->>'fulfilment','paymentResponsibility','platform','currency','GBP',
    'totalPence',(p_input->>'totalPence')::integer,'placedAt',mealdeck_private.marketplace_timestamp(placed),
    'items',items,'notes',p_input->>'notes');
end $$;

create function mealdeck_private.marketplace_record_state(p_order uuid,p_state text,p_observed timestamptz)
returns void language plpgsql security definer set search_path='' as $$
declare o mealdeck_private.marketplace_orders%rowtype;
begin
  select * into o from mealdeck_private.marketplace_orders where id=p_order for update;
  -- Old snapshots never roll a platform order backwards or undo cancellation.
  if p_observed<o.observed_at then return; end if;
  if mealdeck_private.marketplace_state_rank(p_state)<mealdeck_private.marketplace_state_rank(o.platform_state) then
    update mealdeck_private.marketplace_orders set hold_reason=coalesce(hold_reason,'state_regressed'),
      revision=revision+1 where id=p_order and hold_reason is null;
    return;
  end if;
  update mealdeck_private.marketplace_orders set platform_state=p_state,observed_at=p_observed,
    revision=revision+case when platform_state<>p_state then 1 else 0 end where id=p_order;
  if p_state='cancelled' then
    update mealdeck_private.marketplace_commands set status='needs_checking',result_outcome='platform_cancelled'
      where order_id=p_order and status in ('queued','sending');
  else
    update mealdeck_private.marketplace_commands set status='confirmed',confirmed_at=p_observed,
      result_outcome='observed' where order_id=p_order and status in ('queued','sending','needs_checking','unsupported')
      and created_at<=p_observed and mealdeck_private.marketplace_action_observed(action,p_state);
  end if;
end $$;

create function public.mealdeck_marketplace_bridge(
  p_tenant uuid,p_location uuid,p_connector uuid,p_token_hash text,p_operation text,p_payload jsonb
) returns jsonb language plpgsql security definer set search_path='' set lock_timeout='3s' as $$
declare c mealdeck_private.marketplace_connectors%rowtype;o mealdeck_private.marketplace_orders%rowtype;
  cmd mealdeck_private.marketplace_commands%rowtype;v_snapshot jsonb;item jsonb;
  observed timestamptz;replayed boolean;position integer:=0;mode text;result_state text;outcome text;readback_valid boolean:=false;
begin
  -- HTTP authentication is not the only boundary. Each credential is bound to
  -- one exact store and independently commissioned profile in this database.
  select * into c from mealdeck_private.marketplace_connectors where id=p_connector
    and tenant_id=p_tenant and location_id=p_location and token_hash=p_token_hash for update;
  if not found or p_token_hash is null or not c.enabled or c.commissioned_at is null
    or not exists(select 1 from public.tenant_locations where tenant_id=p_tenant and id=p_location and active) then
    raise exception 'mealdeck_marketplace_unauthorized'; end if;
  if jsonb_typeof(p_payload) is distinct from 'object' or octet_length(p_payload::text)>524288
    or p_payload->'evidence' is distinct from jsonb_build_object('profileId',c.profile_id,'profileVersion',c.profile_version) then
    raise exception 'mealdeck_marketplace_profile_mismatch'; end if;

  if p_operation='heartbeat' then
    observed:=(p_payload->>'observedAt')::timestamptz;
    if observed is null or not isfinite(observed) or observed<now()-interval '5 minutes'
      or observed>now()+interval '30 seconds' or coalesce(p_payload->>'status','') not in ('healthy','degraded')
      or p_payload->'capabilities' is distinct from c.capabilities
      or (p_payload->>'errorCode' is not null and p_payload->>'errorCode' not in (
        'ui_unavailable','identity_mismatch','profile_mismatch','session_required','device_unavailable',
        'observation_incomplete','command_uncertain','bridge_error'))
      or (p_payload->>'status'='healthy' and p_payload->>'errorCode' is not null) then
      raise exception 'mealdeck_marketplace_invalid_heartbeat'; end if;
    if c.last_seen_at is null or observed>=c.last_seen_at then
      update mealdeck_private.marketplace_connectors set last_seen_at=observed,
        health_status=p_payload->>'status',health_error_code=p_payload->>'errorCode' where id=p_connector;
    end if;
    return jsonb_build_object('ok',true,'platform',c.platform,'externalStoreId',c.external_store_id,
      'profileId',c.profile_id,'profileVersion',c.profile_version,'capabilities',c.capabilities,
      'enabled',true,'serverTime',mealdeck_private.marketplace_timestamp(now()));

  elsif p_operation='observe' then
    v_snapshot:=mealdeck_private.marketplace_normalise_observation(p_payload);
    if v_snapshot->>'platform' is distinct from c.platform or v_snapshot->>'externalStoreId' is distinct from c.external_store_id then
      raise exception 'mealdeck_marketplace_identity_mismatch'; end if;
    observed:=(p_payload->>'observedAt')::timestamptz;
    select * into o from mealdeck_private.marketplace_orders where connector_id=p_connector
      and external_order_id=v_snapshot->>'externalOrderId' for update;
    replayed:=found;
    if not replayed then
      insert into mealdeck_private.marketplace_orders(connector_id,tenant_id,location_id,external_order_id,
        display_reference,snapshot,fulfilment,currency,total_pence,placed_at,notes,platform_state,observed_at,imported_after_handover)
        values(p_connector,p_tenant,p_location,v_snapshot->>'externalOrderId',v_snapshot->>'displayReference',v_snapshot,
          v_snapshot->>'fulfilment','GBP',(v_snapshot->>'totalPence')::integer,(v_snapshot->>'placedAt')::timestamptz,
          v_snapshot->>'notes',p_payload->>'state',observed,p_payload->>'state'='handed_over') returning * into o;
      for item in select value from jsonb_array_elements(v_snapshot->'items') loop
        position:=position+1;
        insert into mealdeck_private.marketplace_order_items(order_id,connector_id,external_line_id,position,
          name,quantity,unit_price_pence,modifiers,notes) values(o.id,p_connector,item->>'externalLineId',position,
          item->>'name',(item->>'quantity')::integer,(item->>'unitPricePence')::integer,item->'modifiers',item->>'notes');
      end loop;
    elsif o.snapshot is distinct from v_snapshot then
      update mealdeck_private.marketplace_orders set hold_reason='snapshot_changed',revision=revision+1
        where id=o.id and hold_reason is distinct from 'snapshot_changed';
    end if;
    if not exists(select 1 from (
      select previous.snapshot,previous.platform_state from mealdeck_private.marketplace_observations previous
        where previous.order_id=o.id order by previous.sequence desc limit 1
    ) latest where latest.snapshot=v_snapshot and latest.platform_state=p_payload->>'state') then
      insert into mealdeck_private.marketplace_observations(connector_id,order_id,observed_at,platform_state,snapshot,profile_id,profile_version)
        values(p_connector,o.id,observed,p_payload->>'state',v_snapshot,c.profile_id,c.profile_version);
    end if;
    perform mealdeck_private.marketplace_record_state(o.id,p_payload->>'state',observed);
    select * into o from mealdeck_private.marketplace_orders where id=o.id;
    return jsonb_build_object('ok',true,'orderId',o.id,'replayed',replayed,'held',o.imported_after_handover or o.hold_reason is not null or o.platform_state='cancelled',
      'platformState',o.platform_state,'receivedAt',mealdeck_private.marketplace_timestamp(o.received_at));

  elsif p_operation='claim' then
    -- One physical merchant surface has one writer. An unexpired lease blocks
    -- another command, and command order is retained within each order.
    if c.health_status<>'healthy' or c.last_seen_at is null or c.last_seen_at<now()-interval '2 minutes'
      or exists(select 1 from mealdeck_private.marketplace_commands where connector_id=p_connector
        and status='sending' and lease_expires_at>now()) then return jsonb_build_object('command',null); end if;
    select q.* into cmd from mealdeck_private.marketplace_commands q
      join mealdeck_private.marketplace_orders m on m.id=q.order_id and m.connector_id=q.connector_id
      where q.connector_id=p_connector and q.status in ('queued','sending')
        and m.hold_reason is null and m.platform_state<>'cancelled'
        and not exists(select 1 from mealdeck_private.marketplace_commands earlier
          where earlier.order_id=q.order_id and earlier.sequence<q.sequence
            and earlier.status in ('queued','sending','needs_checking'))
      order by case when q.status='sending' then 0 else 1 end,q.sequence limit 1 for update of q;
    if not found then return jsonb_build_object('command',null); end if;
    select * into o from mealdeck_private.marketplace_orders where id=cmd.order_id for update;
    if c.capabilities->cmd.action is distinct from 'true'::jsonb then
      update mealdeck_private.marketplace_commands set status='unsupported',result_outcome='capability_unavailable' where id=cmd.id;
      return jsonb_build_object('command',null);
    end if;
    mode:=case when cmd.execute_claimed_at is null then 'execute' else 'reconcile' end;
    update mealdeck_private.marketplace_commands set status='sending',lease_token=gen_random_uuid(),
      lease_expires_at=now()+interval '90 seconds',execute_claimed_at=coalesce(execute_claimed_at,now()),
      reconcile_claimed_at=case when mode='reconcile' then now() else null end where id=cmd.id returning * into cmd;
    return jsonb_build_object('command',jsonb_build_object('commandId',cmd.id,'leaseToken',cmd.lease_token,
      'leaseExpiresAt',mealdeck_private.marketplace_timestamp(cmd.lease_expires_at),'mode',mode,
      'platform',c.platform,'externalStoreId',c.external_store_id,'externalOrderId',o.external_order_id,
      'displayReference',o.display_reference,'action',cmd.action,'expectedState',o.platform_state));

  elsif p_operation='result' then
    select * into cmd from mealdeck_private.marketplace_commands where id=(p_payload->>'commandId')::uuid
      and connector_id=p_connector for update;
    if not found or cmd.lease_token is distinct from (p_payload->>'leaseToken')::uuid then
      raise exception 'mealdeck_marketplace_lease_conflict'; end if;
    select * into o from mealdeck_private.marketplace_orders where id=cmd.order_id for update;
    outcome:=p_payload->>'outcome';
    if coalesce(outcome,'') not in ('confirmed','not_applied','uncertain','unsupported') then
      raise exception 'mealdeck_marketplace_invalid_result'; end if;
    if outcome='confirmed' or p_payload ?| array['externalStoreId','externalOrderId','displayReference'] then
      if p_payload->>'externalStoreId' is distinct from c.external_store_id
        or p_payload->>'externalOrderId' is distinct from o.external_order_id
        or p_payload->>'displayReference' is distinct from o.display_reference then
        raise exception 'mealdeck_marketplace_identity_mismatch'; end if;
    end if;
    -- A response retry after a previous accepted readback is harmless.
    if cmd.status='confirmed' then
      return jsonb_build_object('ok',true,'commandId',cmd.id,'status','confirmed'); end if;
    if cmd.status<>'sending' or cmd.lease_expires_at<=now() then
      raise exception 'mealdeck_marketplace_lease_conflict'; end if;
    result_state:=case outcome when 'unsupported' then 'unsupported' else 'needs_checking' end;
    if outcome='confirmed' then
      observed:=(p_payload->>'observedAt')::timestamptz;
      if observed is null or not isfinite(observed) or observed<coalesce(cmd.reconcile_claimed_at,cmd.execute_claimed_at)
        or observed<now()-interval '5 minutes' or observed>now()+interval '30 seconds'
        or not coalesce(mealdeck_private.marketplace_action_observed(cmd.action,p_payload->>'observedState'),false)
        or o.platform_state='cancelled' or o.hold_reason is not null then
        raise exception 'mealdeck_marketplace_invalid_confirmation'; end if;
      perform mealdeck_private.marketplace_record_state(o.id,p_payload->>'observedState',observed);
      readback_valid:=true;
      select * into o from mealdeck_private.marketplace_orders where id=o.id;
      if o.hold_reason is not null or not coalesce(mealdeck_private.marketplace_action_observed(cmd.action,o.platform_state),false) then
        result_state:='needs_checking';
      else result_state:='confirmed'; end if;
    elsif p_payload ?& array['externalStoreId','externalOrderId','displayReference','observedAt']
      and mealdeck_private.marketplace_state_rank(p_payload->>'observedState')>=0 then
      -- A failed/uncertain action may still discover a definite cancellation.
      -- Preserve that exact-order observation immediately without claiming the
      -- requested action succeeded or allowing another execution attempt.
      observed:=(p_payload->>'observedAt')::timestamptz;
      if observed is null or not isfinite(observed) or observed<coalesce(cmd.reconcile_claimed_at,cmd.execute_claimed_at)
        or observed<now()-interval '5 minutes' or observed>now()+interval '30 seconds' then
        raise exception 'mealdeck_marketplace_invalid_observation'; end if;
      perform mealdeck_private.marketplace_record_state(o.id,p_payload->>'observedState',observed);
      readback_valid:=true;
      if p_payload->>'observedState'='cancelled' then result_state:='needs_checking'; end if;
    end if;
    update mealdeck_private.marketplace_commands set status=result_state,result_outcome=outcome,
      observed_state=case when readback_valid then p_payload->>'observedState' else null end,
      result_readback_at=case when readback_valid then observed else null end,
      result_profile_id=c.profile_id,result_profile_version=c.profile_version,
      confirmed_at=case when result_state='confirmed' then observed else null end where id=cmd.id;
    return jsonb_build_object('ok',true,'commandId',cmd.id,'status',result_state);
  end if;
  raise exception 'mealdeck_marketplace_invalid_operation';
end $$;

create function mealdeck_private.marketplace_order_card(p_order uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare o mealdeck_private.marketplace_orders%rowtype;c mealdeck_private.marketplace_connectors%rowtype;
  items jsonb;ticket_items jsonb;v text;prep text;pass text;station_name text;station_active boolean;brand_name text;
begin
  select * into o from mealdeck_private.marketplace_orders where id=p_order;
  select * into c from mealdeck_private.marketplace_connectors where id=o.connector_id;
  select name,active into station_name,station_active from public.kitchen_stations
    where id=c.station_id and tenant_id=c.tenant_id and location_id=c.location_id;
  select name into brand_name from public.tenant_brands where id=c.brand_id and tenant_id=c.tenant_id;
  v:=mealdeck_private.marketplace_version(p_order);
  prep:=case when o.ready_at is not null then 'ready' when o.preparing_at is not null then 'preparing' else 'queued' end;
  pass:=case when o.sealed_at is not null then 'sealed' when o.packing_at is not null then 'packing'
    when o.ready_at is not null then 'ready_to_pack' else 'waiting_for_kitchen' end;
  select coalesce(jsonb_agg(jsonb_build_object(
    'order_item_id',i.id,'brand_id',c.brand_id,'brand_name',coalesce(brand_name,c.label),
    'item_name',i.name,'quantity',i.quantity,'unit_pence',i.unit_price_pence,
    'modifiers',coalesce((select jsonb_agg(case when (m->>'quantity')::integer=1 then m->>'name'
      else (m->>'quantity')||' × '||(m->>'name') end order by n)
      from jsonb_array_elements(i.modifiers) with ordinality e(m,n)),'[]'::jsonb),
    'notes',i.notes,'participant_name',null,'status',case when i.ready_at is not null then 'ready'
      when o.preparing_at is not null then 'preparing' else 'queued' end) order by i.position),'[]'::jsonb)
    into items from mealdeck_private.marketplace_order_items i where i.order_id=p_order;
  select coalesce(jsonb_agg(item||jsonb_build_object('ticket_item_id',item->'order_item_id') order by n),'[]'::jsonb)
    into ticket_items from jsonb_array_elements(items) with ordinality e(item,n);
  return jsonb_build_object('order_id',o.id,'version',v,'preparation_status',prep,
    -- Legacy code is an ASCII, non-authoritative placeholder. The complete
    -- source reference is carried only in marketplace.display_reference.
    'display_code',left(o.id::text,8),'order_number',null,
    'created_at',mealdeck_private.marketplace_timestamp(o.placed_at),'released_at',mealdeck_private.marketplace_timestamp(o.received_at),
    'order_status',case when prep='queued' then 'accepted' else prep end,
    'fulfilment',case when o.fulfilment='collection' then 'pickup' else 'delivery' end,
    'notes',o.notes,'group_order',false,'routing_complete',coalesce(station_active,false),
    'blocked_reason',case when not coalesce(station_active,false) then 'routing_incomplete'
      when o.hold_reason is not null then 'snapshot_hold' else null end,
    'items',items,'tickets',jsonb_build_array(jsonb_build_object('ticket_id',o.id,'station_id',c.station_id,
      'station_name',station_name,'status',prep,'version',v,'created_at',mealdeck_private.marketplace_timestamp(o.received_at),
      'started_at',mealdeck_private.marketplace_timestamp(o.preparing_at),'ready_at',mealdeck_private.marketplace_timestamp(o.ready_at),
      'items',ticket_items)),
    'pass',jsonb_build_object('status',pass,'version',v,'updated_at',mealdeck_private.marketplace_timestamp(
      coalesce(o.sealed_at,o.packing_at,o.ready_at,o.preparing_at,o.accepted_at,o.received_at))),
    'accepted_at',mealdeck_private.marketplace_timestamp(o.accepted_at),'cutlery_requested',false,
    'vehicle',null,'pickupContact',null,'marketplace',mealdeck_private.marketplace_metadata(o.id));
end $$;

create function mealdeck_private.marketplace_enqueue_action(p_order uuid,p_action text,p_actor uuid)
returns void language plpgsql security definer set search_path='' as $$
declare o mealdeck_private.marketplace_orders%rowtype;c mealdeck_private.marketplace_connectors%rowtype;s text;
begin
  select * into o from mealdeck_private.marketplace_orders where id=p_order;
  select * into c from mealdeck_private.marketplace_connectors where id=o.connector_id;
  s:=case when mealdeck_private.marketplace_action_observed(p_action,o.platform_state) then 'confirmed'
    when c.capabilities->p_action='true'::jsonb then 'queued' else 'unsupported' end;
  insert into mealdeck_private.marketplace_commands(connector_id,order_id,action,status,actor_id,confirmed_at,result_outcome)
    values(c.id,o.id,p_action,s,p_actor,case when s='confirmed' then o.observed_at else null end,
      case when s='confirmed' then 'already_observed' when s='unsupported' then 'capability_unavailable' else null end)
    on conflict(order_id,action) do nothing;
end $$;

create function public.mealdeck_ops_marketplace_transition(
  p_tenant uuid,p_location uuid,p_order uuid,p_expected_version text,p_action text,
  p_item uuid default null,p_ready boolean default null,p_reference text default null
) returns jsonb language plpgsql security definer set search_path='' set lock_timeout='3s' as $$
declare o mealdeck_private.marketplace_orders%rowtype;c mealdeck_private.marketplace_connectors%rowtype;
  connector uuid;replayed boolean:=false;result_status text;previous boolean;queued_action text;
begin
  perform mealdeck_ops_private.kds_assert_scope(p_tenant,p_location,'orders.status');
  perform 1 from auth.users where id=auth.uid() for share;
  -- Include newly inserted deny rows in the same authorization boundary.
  lock table public.mealdeck_ops_staff_access in share mode;
  perform 1 from public.tenant_locations where id=p_location and tenant_id=p_tenant for share;
  select connector_id into connector from mealdeck_private.marketplace_orders
    where id=p_order and tenant_id=p_tenant and location_id=p_location;
  if not found then raise exception 'mealdeck_marketplace_order_unavailable'; end if;
  select * into c from mealdeck_private.marketplace_connectors where id=connector for update;
  select * into o from mealdeck_private.marketplace_orders where id=p_order
    and tenant_id=p_tenant and location_id=p_location and connector_id=c.id for update;
  perform mealdeck_ops_private.kds_assert_scope(p_tenant,p_location,'orders.status');
  perform 1 from public.kitchen_stations where id=c.station_id and tenant_id=p_tenant and location_id=p_location and active for share;
  if not found then raise exception 'mealdeck_marketplace_connector_unavailable'; end if;
  if o.imported_after_handover then raise exception 'mealdeck_marketplace_already_handed_over'; end if;
  if o.platform_state='cancelled' then raise exception 'mealdeck_marketplace_cancelled'; end if;
  if o.hold_reason is not null then raise exception 'mealdeck_marketplace_snapshot_hold'; end if;
  if coalesce(p_action,'') not in ('accept','preparing','item_ready','packing','sealed','handover')
    or (p_action<>'item_ready' and (p_item is not null or p_ready is not null))
    or (p_action<>'handover' and p_reference is not null) then
    raise exception 'mealdeck_marketplace_invalid_transition'; end if;

  if p_action='accept' then
    replayed:=o.accepted_at is not null;result_status:='accepted';queued_action:='accept';
    if not replayed and not mealdeck_private.marketplace_action_observed('accept',o.platform_state)
      and (c.capabilities->'accept'<>'true'::jsonb or not c.enabled or c.commissioned_at is null
        or c.health_status<>'healthy' or c.last_seen_at is null or c.last_seen_at<now()-interval '2 minutes') then
      raise exception 'mealdeck_marketplace_accept_unavailable'; end if;
  else
    if o.accepted_at is null then raise exception 'mealdeck_marketplace_invalid_transition'; end if;
    if not mealdeck_private.marketplace_action_observed('accept',o.platform_state) then
      raise exception 'mealdeck_marketplace_accept_confirmation_required'; end if;
    case p_action
      when 'preparing' then
        replayed:=o.preparing_at is not null;result_status:='preparing';queued_action:='preparing';
      when 'item_ready' then
        if o.preparing_at is null or p_ready is null or p_item is null then
          raise exception 'mealdeck_marketplace_invalid_transition'; end if;
        if o.packing_at is not null then raise exception 'mealdeck_marketplace_packing_locked'; end if;
        select ready_at is not null into previous from mealdeck_private.marketplace_order_items where id=p_item and order_id=p_order for update;
        if not found then raise exception 'mealdeck_marketplace_invalid_transition'; end if;
        replayed:=previous=p_ready;result_status:=case when o.ready_at is not null then 'ready' else 'preparing' end;
      when 'packing' then
        if o.ready_at is null or exists(select 1 from mealdeck_private.marketplace_order_items where order_id=p_order and ready_at is null) then
          raise exception 'mealdeck_marketplace_all_items_required'; end if;
        replayed:=o.packing_at is not null;result_status:='packing';
      when 'sealed' then
        if o.packing_at is null or o.ready_at is null
          or exists(select 1 from mealdeck_private.marketplace_order_items where order_id=p_order and ready_at is null) then
          raise exception 'mealdeck_marketplace_not_ready'; end if;
        replayed:=o.sealed_at is not null;result_status:='sealed';queued_action:='ready';
      when 'handover' then
        if o.sealed_at is null or exists(select 1 from mealdeck_private.marketplace_order_items where order_id=p_order and ready_at is null) then
          raise exception 'mealdeck_marketplace_not_ready'; end if;
        if p_reference is null then raise exception 'mealdeck_marketplace_handover_reference_required'; end if;
        if (p_reference collate "C") is distinct from (o.display_reference collate "C") then
          raise exception 'mealdeck_marketplace_reference_mismatch'; end if;
        replayed:=o.handed_over_at is not null;result_status:='completed';queued_action:='handover';
    end case;
  end if;
  if not replayed then
    if mealdeck_private.marketplace_version(p_order) is distinct from p_expected_version then
      raise exception 'mealdeck_marketplace_conflict'; end if;
    if o.handed_over_at is not null then raise exception 'mealdeck_marketplace_invalid_transition'; end if;
    case p_action
      when 'accept' then update mealdeck_private.marketplace_orders set accepted_at=now() where id=p_order;
      when 'preparing' then update mealdeck_private.marketplace_orders set preparing_at=now() where id=p_order;
      when 'item_ready' then
        update mealdeck_private.marketplace_order_items set ready_at=case when p_ready then now() else null end where id=p_item and order_id=p_order;
        update mealdeck_private.marketplace_orders set ready_at=case when not exists(
          select 1 from mealdeck_private.marketplace_order_items where order_id=p_order and ready_at is null)
          then coalesce(ready_at,now()) else null end where id=p_order;
        select case when ready_at is not null then 'ready' else 'preparing' end into result_status
          from mealdeck_private.marketplace_orders where id=p_order;
      when 'packing' then update mealdeck_private.marketplace_orders set packing_at=now() where id=p_order;
      when 'sealed' then update mealdeck_private.marketplace_orders set sealed_at=now() where id=p_order;
      when 'handover' then update mealdeck_private.marketplace_orders set handed_over_at=now() where id=p_order;
    end case;
    update mealdeck_private.marketplace_orders set revision=revision+1 where id=p_order;
    if queued_action is not null then perform mealdeck_private.marketplace_enqueue_action(p_order,queued_action,auth.uid()); end if;
    insert into public.mealdeck_ops_audit_log(tenant_id,location_id,actor_id,action,entity_type,entity_id,next_value)
      values(p_tenant,p_location,auth.uid(),'marketplace.kitchen.'||p_action,'marketplace_order',p_order,
        jsonb_build_object('status',result_status,'itemId',p_item,'ready',p_ready));
  end if;
  return jsonb_build_object('ok',true,'replayed',replayed,'order_id',p_order,'status',result_status,
    'marketplace',mealdeck_private.marketplace_metadata(p_order));
end $$;

create function public.mealdeck_ops_marketplace_acknowledge_cancelled(
  p_tenant uuid,p_location uuid,p_order uuid,p_expected_version text
) returns jsonb language plpgsql security definer set search_path='' set lock_timeout='3s' as $$
declare o mealdeck_private.marketplace_orders%rowtype;connector uuid;replayed boolean;
begin
  perform mealdeck_ops_private.kds_assert_scope(p_tenant,p_location,'orders.status');
  perform 1 from auth.users where id=auth.uid() for share;
  lock table public.mealdeck_ops_staff_access in share mode;
  perform 1 from public.tenant_locations where tenant_id=p_tenant and id=p_location for share;
  select connector_id into connector from mealdeck_private.marketplace_orders
    where id=p_order and tenant_id=p_tenant and location_id=p_location;
  if not found then raise exception 'mealdeck_marketplace_order_unavailable'; end if;
  perform 1 from mealdeck_private.marketplace_connectors where id=connector for update;
  select * into o from mealdeck_private.marketplace_orders where id=p_order and tenant_id=p_tenant and location_id=p_location for update;
  perform mealdeck_ops_private.kds_assert_scope(p_tenant,p_location,'orders.status');
  if o.platform_state<>'cancelled' then raise exception 'mealdeck_marketplace_cancel_confirmation_required'; end if;
  replayed:=o.cancellation_acknowledged_at is not null;
  if not replayed then
    if mealdeck_private.marketplace_version(p_order) is distinct from p_expected_version then
      raise exception 'mealdeck_marketplace_conflict'; end if;
    update mealdeck_private.marketplace_orders set cancellation_acknowledged_at=now(),
      cancellation_acknowledged_by=auth.uid(),revision=revision+1 where id=p_order;
    insert into public.mealdeck_ops_audit_log(tenant_id,location_id,actor_id,action,entity_type,entity_id)
      values(p_tenant,p_location,auth.uid(),'marketplace.cancellation.acknowledged','marketplace_order',p_order);
  end if;
  return jsonb_build_object('ok',true,'order_id',p_order,'acknowledged',true,'replayed',replayed);
end $$;

-- Keep the exact previous direct-order function behind the same authenticated
-- wrapper. Direct payment, acceptance, receipts and handoff RPCs are untouched.
alter function public.mealdeck_ops_kds_workflow_board(uuid,uuid) set schema mealdeck_ops_private;
alter function mealdeck_ops_private.mealdeck_ops_kds_workflow_board(uuid,uuid) rename to kds_workflow_board_before_marketplace;
revoke all on function mealdeck_ops_private.kds_workflow_board_before_marketplace(uuid,uuid) from public,anon,authenticated,service_role;
create function public.mealdeck_ops_kds_workflow_board(p_tenant uuid,p_location uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare board jsonb;active jsonb:='[]';completed jsonb:='[]';card jsonb;candidate record;
  active_count integer;completed_count integer;held integer;
begin
  board:=mealdeck_ops_private.kds_workflow_board_before_marketplace(p_tenant,p_location);
  if board->>'readiness'<>'ready' then return board; end if;
  select count(*)::integer,count(*) filter(where hold_reason is not null or platform_state='cancelled')::integer
    into active_count,held from mealdeck_private.marketplace_orders
    where tenant_id=p_tenant and location_id=p_location and handed_over_at is null
      and not imported_after_handover and cancellation_acknowledged_at is null;
  for candidate in select id from mealdeck_private.marketplace_orders
    where tenant_id=p_tenant and location_id=p_location and handed_over_at is null
      and not imported_after_handover and cancellation_acknowledged_at is null
    order by placed_at,id limit 250 loop
    active:=active||jsonb_build_array(mealdeck_private.marketplace_order_card(candidate.id));
  end loop;
  select coalesce(jsonb_agg(value order by (value->>'created_at')::timestamptz,value->>'order_id'),'[]'::jsonb)
    into active from (select value from jsonb_array_elements((board->'orders')||active)
      order by (value->>'created_at')::timestamptz,value->>'order_id' limit 250) limited;
  select count(*)::integer into completed_count from mealdeck_private.marketplace_orders
    where tenant_id=p_tenant and location_id=p_location and not imported_after_handover
      and handed_over_at between now()-interval '12 hours' and now();
  for candidate in select id,handed_over_at from mealdeck_private.marketplace_orders
    where tenant_id=p_tenant and location_id=p_location and not imported_after_handover
      and handed_over_at between now()-interval '12 hours' and now()
    order by handed_over_at desc,id limit 100 loop
    card:=mealdeck_private.marketplace_order_card(candidate.id);
    completed:=completed||jsonb_build_array(jsonb_build_object('order_id',card->'order_id',
      'display_code',card->'display_code','order_number',null,'order_status','fulfilled','handoff_status','handed_off',
      'accepted_at',card->'accepted_at','completed_at',mealdeck_private.marketplace_timestamp(candidate.handed_over_at),
      'fulfilment',card->'fulfilment','pickupContact',null,'group_order',false,'cutlery_requested',false,
      'notes',card->'notes','items',card->'items','marketplace',card->'marketplace'));
  end loop;
  select coalesce(jsonb_agg(value order by (value->>'completed_at')::timestamptz desc,value->>'order_id'),'[]'::jsonb)
    into completed from (select value from jsonb_array_elements((board->'completed_orders')||completed)
      order by (value->>'completed_at')::timestamptz desc,value->>'order_id' limit 100) limited;
  return board||jsonb_build_object('orders',active,'completed_orders',completed,
    'held_order_count',(board->>'held_order_count')::integer+held,
    'remaining_order_count',(board->>'remaining_order_count')::integer+
      greatest(0,jsonb_array_length(board->'orders')+active_count-250),
    'completed_remaining_order_count',(board->>'completed_remaining_order_count')::integer+
      greatest(0,jsonb_array_length(board->'completed_orders')+completed_count-100));
end $$;

create function public.mealdeck_ops_marketplace_connections(p_tenant uuid,p_location uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare enrolled boolean;aal text;result jsonb;
begin
  perform mealdeck_ops_private.kds_assert_scope(p_tenant,p_location,'orders.read');
  if not mealdeck_ops_private.can(p_tenant,p_location,'finance.read')
    or not mealdeck_ops_private.can(p_tenant,p_location,'finance.manage')
    or not exists(select 1 from public.mealdeck_ops_staff_access a where a.user_id=auth.uid()
      and a.tenant_id=p_tenant and a.enabled and (a.location_id is null or a.location_id=p_location)
      and a.role in ('owner','admin')) then raise exception 'mealdeck_marketplace_forbidden'; end if;
  if to_regclass('auth.mfa_factors') is null then raise exception 'mealdeck_marketplace_mfa_unavailable'; end if;
  execute 'select exists(select 1 from auth.mfa_factors where user_id=$1 and status=''verified'')' into enrolled using auth.uid();
  aal:=coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'aal',
    nullif(current_setting('request.jwt.claim.aal',true),''),'aal1');
  if enrolled and aal<>'aal2' then raise exception 'mealdeck_marketplace_mfa_required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('connector_id',c.id,'platform',c.platform,
    'external_store_id',c.external_store_id,'label',c.label,'enabled',c.enabled,'profile_id',c.profile_id,
    'profile_version',c.profile_version,'commissioned_at',mealdeck_private.marketplace_timestamp(c.commissioned_at),
    'last_seen_at',mealdeck_private.marketplace_timestamp(c.last_seen_at),
    'health_status',case when c.health_status='healthy' and (c.last_seen_at is null or c.last_seen_at<now()-interval '2 minutes')
      then 'degraded' else c.health_status end,
    'health_error_code',c.health_error_code,'capabilities',c.capabilities,
    'unresolved_commands',(select count(*) from mealdeck_private.marketplace_commands q
      where q.connector_id=c.id and q.status in ('queued','sending','needs_checking'))) order by c.platform,c.label,c.id),'[]'::jsonb)
    into result from (select * from mealdeck_private.marketplace_connectors
      where tenant_id=p_tenant and location_id=p_location order by platform,label,id limit 100) c;
  return result;
end $$;

do $acl$ declare fn record; begin
  for fn in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
    where (n.nspname='mealdeck_private' and p.proname like 'marketplace\_%' escape '\')
      or (n.nspname='public' and p.proname in ('mealdeck_marketplace_bridge','mealdeck_ops_marketplace_transition','mealdeck_ops_marketplace_acknowledge_cancelled',
        'mealdeck_ops_marketplace_connections','mealdeck_ops_kds_workflow_board')) loop
    execute format('revoke all on function %s from public,anon,authenticated,service_role',fn.signature);
  end loop;
end $acl$;
grant execute on function public.mealdeck_marketplace_bridge(uuid,uuid,uuid,text,text,jsonb) to service_role;
grant execute on function public.mealdeck_ops_marketplace_transition(uuid,uuid,uuid,text,text,uuid,boolean,text),
  public.mealdeck_ops_marketplace_acknowledge_cancelled(uuid,uuid,uuid,text),
  public.mealdeck_ops_marketplace_connections(uuid,uuid),
  public.mealdeck_ops_kds_workflow_board(uuid,uuid) to authenticated;

comment on table mealdeck_private.marketplace_orders is
  'Frozen platform-managed order authority from an explicitly commissioned store bridge, separate from direct MealDeck payment and numbering.';
comment on table mealdeck_private.marketplace_commands is
  'Scoped staff intentions; one execute lease, thereafter reconciliation only. Local kitchen state never proves platform acceptance.';
commit;
